return [
  {
    json: {
      request_id: 'demo-request-001',
      video_title: 'Fictional product walkthrough',
      video_url: 'https://example.invalid/videos/demo-001',
      summary: 'The fictional video explains a three-step review workflow and ends with one clear next action.',
      confidence: 0.91,
      highlights: [
        { timestamp_seconds: 12, label: 'Problem statement' },
        { timestamp_seconds: 47, label: 'Workflow demonstration' },
        { timestamp_seconds: 83, label: 'Next action' }
      ],
      recipient: 'reviewer@example.invalid'
    }
  },
  {
    json: {
      request_id: 'demo-request-001',
      video_title: 'Fictional product walkthrough duplicate',
      video_url: 'https://example.invalid/videos/demo-001-copy',
      summary: 'This duplicate fixture proves that the same request ID does not reach the email destination twice.',
      confidence: 0.88,
      highlights: [],
      recipient: 'reviewer@example.invalid'
    }
  },
  {
    json: {
      request_id: 'demo-request-002',
      video_title: 'Fictional incomplete analysis',
      video_url: 'https://example.invalid/videos/demo-002',
      summary: '',
      confidence: 0.42,
      highlights: [],
      recipient: 'reviewer@example.invalid'
    }
  }
];

return items.map((item) => {
  const row = item.json;
  const requestId = String(row.request_id || '').trim();
  const title = String(row.video_title || '').trim().replace(/\s+/g, ' ');
  const summary = String(row.summary || '').trim().replace(/\s+/g, ' ');
  const recipient = String(row.recipient || '').trim().toLowerCase();
  const errors = [];

  if (!requestId) errors.push('missing_request_id');
  if (!title) errors.push('missing_video_title');
  if (!summary) errors.push('missing_summary');
  if (!recipient.endsWith('@example.invalid')) errors.push('recipient_must_use_example.invalid');

  let videoUrl = '';
  try {
    const parsed = new URL(String(row.video_url || ''));
    if (parsed.hostname !== 'example.invalid') throw new Error('public_demo_domain_only');
    parsed.search = '';
    parsed.hash = '';
    videoUrl = parsed.toString();
  } catch {
    errors.push('invalid_or_non_example_video_url');
  }

  const highlights = Array.isArray(row.highlights)
    ? row.highlights.map((highlight) => ({
        timestamp_seconds: Math.max(0, Number(highlight.timestamp_seconds || 0)),
        label: String(highlight.label || '').trim()
      })).filter((highlight) => highlight.label)
    : [];

  const confidence = Math.max(0, Math.min(1, Number(row.confidence || 0)));

  return {
    json: {
      request_id: requestId,
      video_title: title,
      video_url: videoUrl,
      summary,
      confidence,
      highlights,
      recipient,
      validation_errors: errors,
      needs_review: errors.length > 0,
      send_email: errors.length === 0
    }
  };
});

const seen = new Set();
return items.map((item) => {
  const key = String(item.json.request_id || '').toLowerCase();
  if (seen.has(key)) {
    return {
      json: {
        ...item.json,
        validation_errors: [...item.json.validation_errors, 'duplicate_request_id'],
        needs_review: true,
        send_email: false
      }
    };
  }
  seen.add(key);
  return { json: { ...item.json, delivery_key: key } };
});

return items.map((item) => ({
  json: {
    request_id: item.json.request_id,
    video_title: item.json.video_title,
    status: 'human_review_required',
    send_email: false,
    review_reasons: item.json.validation_errors,
    next_action: 'Correct the sanitized fixture and rerun before configuring any live destination'
  }
}));

return items.map((item) => {
  const row = item.json;
  const highlightLines = row.highlights.length
    ? row.highlights.map((highlight) => `- ${highlight.timestamp_seconds}s: ${highlight.label}`).join('\n')
    : '- No highlights supplied';
  const confidencePercent = Math.round(row.confidence * 100);
  const subject = `Video analysis report | ${row.video_title} | ${row.request_id}`;
  const body = [
    `Summary: ${row.summary}`,
    `Confidence: ${confidencePercent}%`,
    '',
    'Highlights:',
    highlightLines,
    '',
    `Source: ${row.video_url}`,
    `Request ID: ${row.request_id}`
  ].join('\n');

  return {
    json: {
      request_id: row.request_id,
      delivery_key: row.delivery_key,
      email: {
        from: 'no-reply@example.invalid',
        to: row.recipient,
        subject,
        body
      },
      status: 'email_payload_ready'
    }
  };
});
